export const SKILLS = [{"slug": "derzhit-golovu", "chip": "Держит голову", "h1": "Когда ребёнок начинает держать голову", "short": "2–4 мес", "v": "К 2 месяцам — лёжа на животе, к 4 — уверенно на руках", "text": "К 2 месяцам большинство детей поднимают голову, лёжа на животе, а к 4 месяцам — ровно держат её без поддержки, когда взрослый держит их на руках. «Большинство» у CDC значит минимум 75% детей этого возраста.", "blocks": [{"title": "Как это происходит по месяцам", "items": ["Первые недели. Шею ребёнок почти не контролирует, голову нужно поддерживать.", "1 месяц. Лёжа на животе, поворачивает голову из стороны в сторону; без поддержки голова запрокидывается назад.", "2 месяца. Лёжа на животе, поднимает и удерживает голову.", "4 месяца. Ровно держит голову без поддержки на руках у взрослого, а лёжа на животе — приподнимается на локтях и предплечьях."], "text": []}, {"title": "Что помогает", "items": [], "text": ["Выкладывание на живот, пока ребёнок бодрствует. CDC советует класть игрушки перед ним на уровне глаз: так он тренируется поднимать голову. Одного на животе ребёнка не оставляют, а если он засыпает — перекладывают на спину, на жёсткий матрас без подушек и одеял."]}], "faq": [{"q": "Ребёнку 3 месяца, а голову он держит неуверенно. Это нормально?", "a": "Пункт «ровно держит голову без поддержки» стоит в чек-листе CDC на 4 месяца, а не на 3. Если к 4 месяцам этого нет, расскажите педиатру, не откладывая, — так CDC советует поступать с любым пунктом чек-листа."}]}, {"slug": "perevorachivaetsya", "chip": "Переворачивается", "h1": "Когда ребёнок начинает переворачиваться", "short": "5–7 мес", "v": "С живота на спину — к 6 месяцам, в обе стороны — к 7", "text": "К 6 месяцам минимум 75% детей переворачиваются с живота на спину. По данным Американской академии педиатрии, нужные для переворота навыки появляются около 5 месяцев, а к 7 месяцам ребёнок, вероятно, сможет переворачиваться в обе стороны — но сроки у разных детей различаются.", "blocks": [{"title": "В какую сторону сначала", "items": [], "text": ["Большинство детей сначала переворачиваются с живота на спину, а потом — со спины на живот. Обратный порядок, подчёркивает AAP, совершенно нормален.", "В 3 месяца большинство детей ещё не умеют переворачиваться со спины на живот, хотя некоторые уже начинают. А вот перекатиться с живота на спину, сильно оттолкнувшись ногами, ребёнок скоро сможет."]}], "faq": [{"q": "Ребёнку 5 месяцев, и он не переворачивается. Пора беспокоиться?", "a": "В чек-листе CDC переворот с живота на спину стоит на отметке 6 месяцев, и AAP отдельно оговаривает, что сроки у детей разные. Если переворотов нет и к 6 месяцам, скажите об этом педиатру."}]}, {"slug": "sidit", "chip": "Сидит и садится", "h1": "Когда ребёнок начинает сидеть", "short": null, "v": null, "text": "", "blocks": [{"title": "А присаживать можно?", "items": [], "text": ["Американская академия педиатрии прямо советует помогать. Когда ребёнок, лёжа на животе, уже приподнимает грудь, его можно придерживать или подпирать ему спину подушками, пока он учится держать равновесие. Сначала он сидит «треногой» — наклонившись вперёд и опираясь на руки, а к 6–8 месяцам, если его посадить, сидит уже без опоры на руки.", "Утверждения, что присаживание с поддержкой вредит позвоночнику, мы не нашли ни у ВОЗ, ни у CDC, ни у AAP, ни у британской NHS. Отдельных правил для девочек там тоже нет.", "NHS предупреждает о другом: если ребёнок подолгу находится в креслах и сиденьях, которые фиксируют его в сидячей позе, это может задержать умение садиться самостоятельно. Поэтому ходунками, прыгунками и сиденьями советуют пользоваться не дольше 20 минут за раз."]}, {"title": "Когда сказать врачу", "items": [], "text": ["AAP просит сообщить педиатру, если к 9 месяцам ребёнок не сидит самостоятельно."]}], "faq": [{"q": "Во сколько месяцев ребёнок садится сам?", "a": "Самостоятельно принимать сидячее положение большинство детей умеют к 9 месяцам: этот пункт стоит в чек-листе CDC рядом с «сидит без поддержки»."}, {"q": "Мальчики и девочки садятся в разное время?", "a": "Практически нет. В исследовании ВОЗ девочки начинали сидеть без поддержки в среднем меньше чем на 5 дней раньше мальчиков, а стоять самостоятельно — примерно на 7 дней раньше; по остальным навыкам значимой разницы не было. Авторы назвали эти различия мелкими и непоследовательными и отдельных норм по полу делать не стали — поэтому окна общие."}]}, {"slug": "polzaet", "chip": "Ползает", "h1": "Когда ребёнок начинает ползать", "short": null, "v": null, "text": "", "blocks": [{"title": "Если ребёнок не ползает", "items": [], "text": ["Американская академия педиатрии: некоторые дети никогда не ползают, а передвигаются по-своему — на попе или по-пластунски на животе. Если ребёнок согласованно работает обеими сторонами тела и одинаково пользуется обеими руками и ногами, повода для беспокойства нет.", "NHS: ползать дети начинают примерно в 7–10 месяцев, но ползают не все. Посоветоваться со специалистом стоит, если к 12 месяцам ребёнок вообще никак не пытается передвигаться.", "В чек-листах CDC на 9 и 12 месяцев пункта «ползает» нет."]}], "faq": []}, {"slug": "vstaet-i-stoit", "chip": "Стоит и встаёт", "h1": "Когда ребёнок начинает стоять и вставать", "short": null, "v": null, "text": "", "blocks": [{"title": "Прыгунки и ходунки не ускоряют", "items": [], "text": ["NHS: ходунки и прыгунки приучают вставать на цыпочки и, если пользоваться ими много, могут задержать ходьбу."]}], "faq": []}, {"slug": "hodit", "chip": "Ходит", "h1": "Когда ребёнок начинает ходить", "short": null, "v": null, "text": "", "blocks": [{"title": "Ходунки не помогают", "items": [], "text": ["Американская академия педиатрии призывает запретить производство и продажу ходунков на колёсах; в Канаде они уже запрещены. Научиться ходить они не помогают, а начало ходьбы могут даже отсрочить.", "Главная причина — травмы. С 1990 по 2014 год в отделения неотложной помощи США попали около 230 тысяч детей младше 15 месяцев с травмами из-за ходунков: у 90,6% были травмы головы или шеи, 74,1% упали в ходунках с лестницы.", "NHS добавляет: ходунки и прыгунки приучают вставать на цыпочки и при частом использовании могут задержать ходьбу."]}], "faq": [{"q": "Мальчики начинают ходить позже девочек?", "a": "Устойчивых и практически значимых различий между мальчиками и девочками исследование ВОЗ не нашло: там, где разница есть, она измеряется днями. Поэтому окно одно."}]}, {"slug": "ulybaetsya-i-smeetsya", "chip": "Улыбается и смеётся", "h1": "Когда ребёнок начинает улыбаться и смеяться", "short": "2–6 мес", "v": "Улыбка в ответ — к 2 месяцам, смех — к 6", "text": "К 2 месяцам большинство детей улыбаются, когда с ними говорят или им улыбаются; к 4 — посмеиваются, когда их смешат; к 6 — смеются. Первая настоящая улыбка, по данным AAP, может появиться примерно с шестой недели.", "blocks": [{"title": "Улыбка во сне — ещё не та улыбка", "items": [], "text": ["Улыбки первых недель, особенно во сне, — рефлекторные движения лица. Настоящая, обращённая к вам, появляется позже: примерно с шестой недели.", "К 4 месяцам ребёнок уже улыбается сам, чтобы привлечь ваше внимание. В 4–6 месяцев, по данным ASHA, он хихикает и смеётся."]}], "faq": []}, {"slug": "gulit-i-lepechet", "chip": "Гулит и лепечет", "h1": "Когда ребёнок начинает гулить, агукать и лепетать", "short": "2–9 мес", "v": "Гуление — с 2–4 месяцев, лепет слогами — с 7–9", "text": "Гулить — тянуть гласные вроде «а-а-а», «о-о-о» — ребёнок может начать примерно в 2 месяца; к 4 месяцам это делают минимум 75% детей. Лепет цепочками слогов — «ма-ма-ма», «ба-ба-ба» — появляется в 7–9 месяцев и к 9 месяцам есть у большинства.", "blocks": [{"title": "Что происходит между гулением и лепетом", "items": ["С рождения до 3 месяцев: гулит, издаёт звуки удовольствия.", "4–6 месяцев: произносит разные гласные, иногда вместе с согласным; лепечет, подражая речи, в том числе звуками «п», «б», «м».", "К 6 месяцам: «разговаривает» с вами по очереди, фыркает губами, взвизгивает.", "7–9 месяцев: лепечет длинными цепочками слогов."], "text": []}, {"title": "Оговорка про язык", "items": [], "text": ["Нормы ASHA — это возраст, к которому навык есть минимум у 75% детей, говорящих на американском английском. Ассоциация прямо пишет, что у детей, говорящих на других языках, последовательность и темпы могут отличаться."]}], "faq": []}, {"slug": "govorit", "chip": "Говорит", "h1": "Когда ребёнок начинает говорить", "short": "1–2 года", "v": "Первые слова — около года, фразы из двух слов — к двум", "text": "В 10–12 месяцев ребёнок говорит одно-два слова — «мама», «папа», «пока»; к году большинство детей называют родителя «мама», «папа» или другим особым словом. К двум годам большинство соединяют хотя бы два слова: «ещё молока».", "blocks": [{"title": "Речь по возрасту", "items": [], "text": []}, {"title": "Сколько слов в 2 года: источники расходятся", "items": [], "text": ["Часть расхождения — в шкале: CDC берёт возраст, к которому навык есть минимум у 75% детей, а AAP и MedlinePlus описывают типичного двухлетку. Но ASHA пользуется тем же порогом 75% и всё равно ставит 50 слов раньше — так что источники действительно расходятся. Общее у всех одно: около 50 слов — нижний ориентир, а разброс у здоровых детей большой."]}, {"title": "«Мама» случайно и «мама» осознанно", "items": [], "text": ["AAP описывает это так: на слова вроде «мама» и «пока-пока» ребёнок сначала натыкается случайно, по вашей радости понимает, что сказал что-то значимое, и вскоре начинает говорить «мама», чтобы позвать вас. Возраст первых узнаваемых слов сильно различается: у кого-то к году два-три слова, но чаще речь годовалого — «тарабарщина» с интонациями настоящей речи."]}, {"title": "Оговорка про язык", "items": [], "text": ["Нормы ASHA рассчитаны на детей, говорящих на американском английском, и ассоциация прямо пишет, что в других языках последовательность и темпы могут отличаться. Чек-листы CDC опираются и на исследования из неанглоязычных стран, но формулировки и примеры слов в них английские. Поэтому число слов — ориентир для разговора с врачом, а не порог."]}], "faq": [{"q": "Правда, что мальчики начинают говорить позже?", "a": "В чек-листах CDC и ASHA сроки одни для всех детей: отдельных списков для мальчиков и девочек там нет. В российском пособии для врачей есть замечание, что девочки овладевают речью раньше, но отдельных сроков для них не даёт и оно."}, {"q": "Ребёнку 2 года, и он почти не говорит. Что делать?", "a": "Сверьтесь с чек-листом на 2 года: большинство детей к этому возрасту соединяют два слова, показывают предметы в книге и части тела, пользуются жестами. Если чего-то из этого нет — расскажите педиатру, не откладывая. Отдельно AAP просит сообщать врачу, если ребёнок перестал говорить или делать то, что раньше умел."}]}, {"slug": "uznaet-i-otklikaetsya", "chip": "Узнаёт маму, откликается на имя", "h1": "Когда ребёнок начинает узнавать маму и откликаться на имя", "short": "1–9 мес", "v": "Узнаёт по голосу — к месяцу, откликается на имя — к 9 месяцам", "text": "К месяцу ребёнок способен узнавать родителя по голосу, даже из другой комнаты; в первые три месяца — узнаёт близких, а к 6 месяцам большинство детей узнают знакомых людей. Смотреть на взрослого, когда тот зовёт по имени, большинство начинает к 9 месяцам.", "blocks": [{"title": "Боязнь чужих — тоже этап", "items": [], "text": ["К 9 месяцам большинство детей стесняются, жмутся к близкому взрослому или пугаются при незнакомых людях и реагируют, когда родитель уходит.", "AAP называет тревогу при незнакомцах одной из первых эмоциональных вех и отдельно пишет, что для этого возраста она нормальна. Тревога разлуки обычно достигает пика между 10 и 18 месяцами и затухает во второй половине второго года."]}], "faq": [{"q": "Ребёнку год, а на имя он откликается не всегда", "a": "AAP формулирует ориентир для года мягко: откликается на имя «в большинстве случаев». В чек-листе CDC пункт «смотрит на вас, когда вы зовёте его по имени» стоит на 9 месяцах; если к году этого нет совсем, расскажите педиатру."}]}, {"slug": "vidit-i-slyshit", "chip": "Видит и слышит", "h1": "Когда новорождённый начинает видеть и слышать", "short": "с рождения", "v": "Слышит ещё до рождения, видит — с первых дней, но лучше всего на 20–30 см", "text": "Слух у плода работает уже на 19–21-й неделе беременности. Видит новорождённый тоже сразу — свет, формы, лица, движение, — но вдаль размыто: лучше всего на расстоянии 20–30 см.", "blocks": [{"title": "Зрение по месяцам", "items": ["Около 1 месяца: ненадолго фокусируется на вашем лице.", "Около 2 месяцев: следит глазами за движущимся предметом; к 2 месяцам большинство детей следят за вами взглядом и несколько секунд смотрят на игрушку.", "До 2–3 месяцев глаза могут временами «блуждать» и косить — к этому возрасту это должно проходить.", "В 3 месяца глаза должны работать согласованно, фокусироваться и следить за предметами; если вы этого не замечаете, AAO советует поговорить с педиатром.", "К 4 месяцам ребёнок лучше различает цвета и оттенки; около 5 месяцев цветовое зрение уже хорошее, хотя и не такое, как у взрослого.", "К 3–5 годам ребёнок с нормальным зрением видит так же хорошо, как взрослый."], "text": []}, {"title": "Слух после рождения", "items": ["К 1 месяцу слух, по данным AAP, уже полностью зрелый; ребёнок реагирует на громкие звуки и может поворачиваться на знакомые голоса.", "К 2 месяцам большинство детей реагируют на громкие звуки, к 4 — поворачивают голову на звук вашего голоса."], "text": []}, {"title": "Когда меняется цвет глаз", "items": [], "text": ["AAP: клеткам, которые вырабатывают пигмент, нужно около года, поэтому называть цвет глаз до первого дня рождения рискованно; после 6 месяцев изменения замедляются, но ещё возможны.", "AAO: примерно к 9 месяцам глаза, вероятно, уже окончательного цвета, хотя небольшие изменения позже — не редкость. У большинства детей цвет перестаёт меняться после первого года, у некоторых — продолжает ещё несколько лет."]}], "faq": []}, {"slug": "zuby", "chip": "Режутся и выпадают зубы", "h1": "Когда у ребёнка режутся и выпадают зубы", "short": "с 6 мес", "v": "Первый зуб — около 6 месяцев, все молочные — к 2–3 годам", "text": "У большинства детей зубы начинают резаться около 6 месяцев, но у кого-то — до 4, а у кого-то — после 12; некоторые рождаются с зубами. Все молочные зубы у большинства детей есть к 2–3 годам. AAP подчёркивает, что разброс велик: у некоторых детей и к первому дню рождения нет ни одного зуба.", "blocks": [{"title": "Молочные зубы: когда режутся и когда выпадают", "items": [], "text": []}, {"title": "Постоянные зубы", "items": [], "text": ["Первыми, в 6–7 лет, появляются первые постоянные моляры и нижние центральные резцы, верхние центральные резцы — в 7–8 лет, зубы мудрости — в 17–21 год. К 21 году обычно прорезаются все 32 постоянных зуба."]}, {"title": "Температура «на зубы»", "items": [], "text": ["AAP: настоящая лихорадка — выше 38 °C — с прорезыванием зубов не связана. Это признак болезни или инфекции, которая может требовать лечения."]}], "faq": []}, {"slug": "spit-vsyu-noch", "chip": "Спит всю ночь", "h1": "Когда ребёнок начинает спать всю ночь", "short": "срока нет", "v": "Единого срока нет: и в год многие просыпаются", "text": "В канадском исследовании (388 детей в 6 месяцев, 369 — в год) в полгода 38% ещё не спали ночью шесть часов подряд, а 57% — восемь; в год таких было 28% и 43%. Связи между непрерывным сном и развитием ребёнка авторы не нашли и предложили умерить ожидания раннего «сна всю ночь».", "blocks": [{"title": "Почему в другой статье написано «в 2–3 месяца»", "items": [], "text": ["Потому что считали разное. В исследовании 2010 года по дневникам 75 семей смотрели, когда ребёнок впервые проспал «всю ночь» — с полуночи до пяти утра, восемь часов подряд или с 22 до 6; по любому из трёх критериев у большинства это впервые случалось в 2–3 месяца. В исследовании 2018 года матерей спрашивали, спит ли ребёнок шесть или восемь часов подряд сейчас, в 6 и в 12 месяцев, — и вышло, что заметная часть детей так не спит. «Однажды получилось» и «получается каждую ночь» — разные вещи."]}, {"title": "Что говорят педиатры", "items": ["AAP: до примерно 4 месяцев у детей нет регулярных циклов сна; для шестимесячного нормально проснуться ночью и через несколько минут снова уснуть.", "NHS: кто-то начинает спать всю ночь быстро, кто-то — очень нескоро; в 3–6 месяцев некоторые дети спят ночью по 5–8 часов и дольше, но не все.", "Конкретного возраста, когда ребёнок «должен» спать всю ночь, на этих страницах ни AAP, ни NHS не называют."], "text": []}], "faq": []}, {"slug": "gorshok", "chip": "Ходит на горшок", "h1": "Когда приучать ребёнка к горшку", "short": "1,5–3 года", "v": "Между 18 месяцами и 3 годами", "text": "Признаки контроля мочевого пузыря и кишечника обычно появляются между 18 и 24 месяцами; в США приучать в среднем начинают между 2 и 3 годами, а к 4 годам большинство детей приучены. NHS: почти всех детей можно приучить к горшку между 18 месяцами и 2,5 года.", "blocks": [{"title": "Признаки готовности по версии AAP", "items": ["остаётся сухим хотя бы два часа подряд днём или после дневного сна;", "видно, что ему нужно в туалет: кряхтит, замирает, присаживается;", "выполняет простые просьбы;", "может дойти до туалета и обратно и помогает себя раздевать;", "не любит мокрый подгузник и просит его сменить;", "просится на горшок или в туалет, хочет «взрослые» трусы."], "text": []}, {"title": "Где источники расходятся", "items": [], "text": ["AAP строит совет вокруг признаков готовности, хотя и оговаривает: начинать можно, как только этого захотят родители и ребёнок. NHS говорит прямо: лучше всего просто начать, ждать знаков или просьб не нужно. В нижней границе — около 18 месяцев — они сходятся."]}], "faq": []}, {"slug": "melkaya-motorika", "chip": "Мелкая моторика и рисование", "h1": "Когда ребёнок начинает брать игрушки, есть ложкой и рисовать", "short": "по возрасту", "v": "Тянется к игрушке — к 6 месяцам, ест ложкой — к 2 годам, рисует круг — к 3", "text": "Это отметки чек-листов CDC — возраст, к которому навык есть минимум у 75% детей.", "blocks": [{"title": "Руки по возрасту", "items": [], "text": []}], "faq": [{"q": "Что должен уметь рисовать ребёнок?", "a": "По чек-листам CDC: к полутора годам — каракули, к 3 годам — круг, если показать как, к 4 — человека хотя бы с тремя частями тела, к 5 — некоторые буквы своего имени."}, {"q": "Когда ребёнок начинает брать мелкие предметы двумя пальцами?", "a": "К году это умеют минимум 75% детей. Офтальмологи называют возраст чуть раньше: около 10 месяцев ребёнок уже достаточно хорошо видит и оценивает расстояние, чтобы взять предмет большим и указательным пальцами."}]}, {"slug": "chitaet-i-pishet", "chip": "Читает и пишет", "h1": "Когда ребёнок начинает читать и писать", "short": "6–7 лет", "v": "Большинство — в 6–7 лет", "text": "При хорошем обучении большинство детей учатся читать в шесть-семь лет, единицы — в четыре, некоторые — в пять, а кому-то нужна индивидуальная помощь и в восемь-девять: так сказано в совместном заявлении американской Национальной ассоциации образования детей младшего возраста и Международной ассоциации чтения. К 5 годам большинство детей пишут некоторые буквы своего имени и называют некоторые буквы.", "blocks": [{"title": "Нужно ли учить читать до школы", "items": [], "text": ["Американская академия педиатрии: если дошкольник ещё не интересуется буквами и книгами, он такой же, как большинство дошкольников, — скорее всего, до начала обучения чтению ему нужен ещё год-два. Подталкивать незачем: часть рано зачитавших детей теряет преимущество ко второму-третьему классу, когда остальные осваивают те же навыки. Поддерживать интерес к учёбе важнее, чем возраст, в котором ребёнок начнёт читать.", "В одном классе kindergarten — это первый, подготовительный год американской школы, 5–6 лет, — отмечают NAEYC и IRA, разброс связанных с грамотностью навыков обычно достигает пяти лет: у одних детей они как у типичного трёхлетки, у других — как у восьмилетки."]}, {"title": "Что бывает до чтения", "items": ["Около 12–18 месяцев: держит книгу, переворачивает картонные страницы, показывает пальцем на картинки.", "Около 18–24 месяцев: называет знакомые картинки, договаривает фразы из любимой книги.", "К 4 годам: держит карандаш пальцами, а не в кулаке; говорит, что будет дальше в знакомой сказке.", "К 5 годам: называет некоторые буквы, пишет некоторые буквы своего имени, узнаёт простые рифмы."], "text": []}, {"title": "Оговорка", "items": [], "text": ["Заявление NAEYC и IRA принято в 1998 году и описывает обучение чтению на английском. Что требуют при приёме в российскую школу — на странице «К школе»."]}], "faq": []}];
